const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 750 } });
  await page.goto('http://localhost:3002');
  await page.screenshot({ path: '/tmp/opencode/insomnio.jpg', type: 'jpeg', quality: 78 });
  await browser.close();
})();

const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 750 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002');
  await page.locator('#startBtn').click();
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/insomnio-game.jpg', type: 'jpeg', quality: 78 });
  console.log(JSON.stringify({ title: await page.title(), errors, canvas: await page.locator('canvas').evaluate(c => [c.width, c.height]), overlayHidden: await page.locator('#overlay').evaluate(e => e.classList.contains('hidden')) }));
  await browser.close();
})();

